{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table pronk-wh.maplemonk.PO_Fact_Items as WITH po_base AS ( SELECT _airbyte_data, SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.po_id\') AS INT64) AS po_id, JSON_VALUE(_airbyte_data, \'$.po_ref_num\') AS po_ref, JSON_VALUE(_airbyte_data, \'$.vendor_name\') AS vendor, CAST(NULL AS STRING) AS buyer, DATE(SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.po_created_date\') AS TIMESTAMP)) AS po_date, DATE(SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.expected_delivery_date\') AS TIMESTAMP)) AS expected_delivery, SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.po_status_id\') AS INT64) AS po_status_id, SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.po_expiry_date\') AS TIMESTAMP) AS po_expiry_date, SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.total_po_value\') AS FLOAT64) AS total_po_value, JSON_VALUE(_airbyte_data, \'$.po_created_warehouse\') AS po_created_warehouse, SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.po_created_warehouse_c_id\') AS INT64) AS po_created_warehouse_c_id, SAFE_CAST(JSON_VALUE(_airbyte_data, \'$.vendor_c_id\') AS INT64) AS vendor_c_id, JSON_VALUE(_airbyte_data, \'$.vendor_location_key\') AS vendor_location_key, JSON_VALUE(_airbyte_data, \'$.po_created_location_key\') AS po_created_location_key, JSON_VALUE(_airbyte_data, \'$.warehouse_id\') AS warehouse_id FROM maplemonk._airbyte_raw_Pronk_Easyecom_purchase_orders ), po_items AS ( SELECT p.*, item FROM po_base p CROSS JOIN UNNEST(JSON_QUERY_ARRAY(p._airbyte_data, \'$.po_items\')) AS item ) SELECT po_id AS `PO_No`, po_ref AS `PO_Ref`, vendor AS `Vendor`, buyer AS `Buyer`, po_date AS `PO_Date`, expected_delivery AS `Expected_Delivery`, DATE_DIFF(CURRENT_DATE(), expected_delivery, DAY) AS `Days_Late`, CASE WHEN expected_delivery IS NULL THEN \'Not yet due\' WHEN DATE_DIFF(CURRENT_DATE(), expected_delivery, DAY) <= 0 THEN \'Not yet due\' WHEN DATE_DIFF(CURRENT_DATE(), expected_delivery, DAY) BETWEEN 1 AND 15 THEN \'1-15 days\' WHEN DATE_DIFF(CURRENT_DATE(), expected_delivery, DAY) BETWEEN 16 AND 30 THEN \'16-30 days\' WHEN DATE_DIFF(CURRENT_DATE(), expected_delivery, DAY) BETWEEN 31 AND 60 THEN \'31-60 days\' WHEN DATE_DIFF(CURRENT_DATE(), expected_delivery, DAY) BETWEEN 61 AND 90 THEN \'61-90 days\' ELSE \'90+ days\' END AS `Delay_Bucket`, COUNT(DISTINCT JSON_VALUE(item, \'$.sku\')) AS `SKUs`, SUM(SAFE_CAST(JSON_VALUE(item, \'$.original_quantity\') AS INT64)) AS `Ordered_Qty`, SUM(SAFE_CAST(JSON_VALUE(item, \'$.original_quantity\') AS INT64) - SAFE_CAST(JSON_VALUE(item, \'$.pending_quantity\') AS INT64)) AS `Received_Qty`, SUM(SAFE_CAST(JSON_VALUE(item, \'$.pending_quantity\') AS INT64)) AS `Pending_Qty`, SAFE_DIVIDE(SUM(SAFE_CAST(JSON_VALUE(item, \'$.original_quantity\') AS FLOAT64) - SAFE_CAST(JSON_VALUE(item, \'$.pending_quantity\') AS FLOAT64)), SUM(SAFE_CAST(JSON_VALUE(item, \'$.original_quantity\') AS FLOAT64))) AS `Fill_Rate`, SUM(SAFE_CAST(JSON_VALUE(item, \'$.original_quantity\') AS FLOAT64) * SAFE_CAST(JSON_VALUE(item, \'$.item_price\') AS FLOAT64)) AS `PO_Value`, SUM(SAFE_CAST(JSON_VALUE(item, \'$.pending_quantity\') AS FLOAT64) * SAFE_CAST(JSON_VALUE(item, \'$.item_price\') AS FLOAT64)) AS `Pending_Value`, CASE WHEN SUM(SAFE_CAST(JSON_VALUE(item, \'$.pending_quantity\') AS FLOAT64)) > 0 AND expected_delivery < CURRENT_DATE() THEN \'Overdue\' WHEN SUM(SAFE_CAST(JSON_VALUE(item, \'$.pending_quantity\') AS FLOAT64)) > 0 THEN \'Live\' ELSE \'Stale - Close or Chase\' END AS `Flag`, po_ref AS `PO_Ref_Num`, po_status_id AS `PO_Status_ID`, po_expiry_date AS `PO_Expiry_Date`, total_po_value AS `Total_PO_Value`, po_created_warehouse AS `PO_Created_Warehouse`, po_created_warehouse_c_id AS `PO_Created_Warehouse_C_ID`, vendor_c_id AS `Vendor_C_ID`, vendor_location_key AS `Vendor_Location_Key`, po_created_location_key AS `PO_Created_Location_Key`, warehouse_id AS `Warehouse_ID` FROM po_items GROUP BY po_id, po_ref, vendor, buyer, po_date, expected_delivery, po_status_id, po_expiry_date, total_po_value, po_created_warehouse, po_created_warehouse_c_id, vendor_c_id, vendor_location_key, po_created_location_key, warehouse_id;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

